def error_cost(fp, fn, cost_fp=2, cost_fn=10):
    if min(fp, fn, cost_fp, cost_fn) < 0:
        raise ValueError("Counts and costs must be nonnegative")
    return fp * cost_fp + fn * cost_fn


print(error_cost(3, 2))  # 26 illustrative cost units

def fitting_budget(candidates, inner_folds, outer_folds):
    if min(candidates, inner_folds, outer_folds) < 2:
        raise ValueError("Use at least two for this example")
    one_search = candidates * inner_folds + 1
    return outer_folds * one_search + one_search


print(fitting_budget(3, 3, 3))  # 40, final refit included

# ১) পূর্বঘোষিত 64 MB Memory সীমা মেনে সেরা Experiment বাছাই (explicit for loops!)
experiments = [
    {"name": "baseline", "validation_loss": 0.34, "memory_mb": 40},
    {"name": "candidate", "validation_loss": 0.33, "memory_mb": 120},
]

winner = None
for row in experiments:
    if row["memory_mb"] <= 64:
        if winner is None or row["validation_loss"] < winner["validation_loss"]:
            winner = row

print("Feasible winner (<=64MB):", winner["name"])

# ২) গড় Accuracy 92% অথচ ছোট Slice-এ 40% ধস! (কোনো numpy/pandas ছাড়াই!)
y_true = [1] * 100
y_pred = [1] * 88 + [0] * 2 + [1] * 4 + [0] * 6
slices = ["major"] * 90 + ["minor"] * 10

overall_ok = 0
for i in range(len(y_true)):
    if y_true[i] == y_pred[i]:
        overall_ok += 1
print(f"Overall accuracy: {overall_ok / len(y_true):.2f}")

for target_slice in ["major", "minor"]:
    s_total = 0
    s_ok = 0
    for i in range(len(slices)):
        if slices[i] == target_slice:
            s_total += 1
            if y_true[i] == y_pred[i]:
                s_ok += 1
    print(f"Slice {target_slice:5s}: n={s_total:2d}, accuracy={s_ok / s_total:.2f}")

positives = 20
policies = {"loose": (16, 24), "tight": (11, 4)}
scores = {
    label: (5 * (positives - true_positive) + false_positive,
            true_positive + false_positive)
    for label, (true_positive, false_positive) in policies.items()
}
def choose(capacity):
    eligible = [(cost, label) for label, (cost, volume) in scores.items()
                if volume <= capacity]
    return min(eligible)[0] if eligible else None

assert choose(10) is None
print(choose(40), choose(20))

